PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE cart (   id          INTEGER PRIMARY KEY AUTOINCREMENT,   user_id     TEXT NOT NULL,   product_id  TEXT NOT NULL,   name        TEXT NOT NULL,   price       REAL NOT NULL DEFAULT 0,   image       TEXT,   quantity    INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),   created_at  TEXT NOT NULL DEFAULT (datetime('now')),   updated_at  TEXT NOT NULL DEFAULT (datetime('now')),   UNIQUE (user_id, product_id) );
CREATE TABLE orders (   id                   INTEGER PRIMARY KEY AUTOINCREMENT,   order_number         TEXT NOT NULL UNIQUE,   user_id              TEXT NOT NULL,   subtotal             REAL NOT NULL DEFAULT 0,   shipping             REAL NOT NULL DEFAULT 0,   total                REAL NOT NULL DEFAULT 0,   status               TEXT NOT NULL DEFAULT 'pending'                         CHECK (status IN ('pending','paid','processing','shipped','delivered','cancelled')),   payment_method       TEXT,   created_at           TEXT NOT NULL DEFAULT (datetime('now')),   updated_at           TEXT NOT NULL DEFAULT (datetime('now')) , stripe_session_id TEXT);
CREATE TABLE order_items (   id          INTEGER PRIMARY KEY AUTOINCREMENT,   order_id    INTEGER NOT NULL,   product_id  TEXT NOT NULL,   name        TEXT NOT NULL,   price       REAL NOT NULL,   image       TEXT,   quantity    INTEGER NOT NULL CHECK (quantity > 0),   line_total  REAL NOT NULL,   FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE );
CREATE TABLE users (     id              INTEGER PRIMARY KEY AUTOINCREMENT,     google_id       TEXT UNIQUE,     email           TEXT NOT NULL UNIQUE,     name            TEXT NOT NULL,     password        TEXT,     picture         TEXT,     role            TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')),     is_verified     INTEGER NOT NULL DEFAULT 0 CHECK (is_verified IN (0,1)),     status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','blocked','deleted')),     last_login_at   TIMESTAMP,     created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,     updated_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP , verification_code TEXT, verification_code_expires_at TIMESTAMP, public_id TEXT);
CREATE TABLE products (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL,   price REAL NOT NULL,   sale_price REAL,   image TEXT NOT NULL,   filter_category TEXT,   type TEXT,   badge TEXT DEFAULT '',   is_new_in INTEGER DEFAULT 0,   is_on_sale INTEGER DEFAULT 0,   featured INTEGER DEFAULT 0,   status TEXT DEFAULT 'active',   created_at TEXT DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT DEFAULT CURRENT_TIMESTAMP , category_id INTEGER REFERENCES categories(id), brand_id INTEGER REFERENCES brands(id), description TEXT);
CREATE TABLE categories (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL UNIQUE,   slug TEXT NOT NULL UNIQUE,   created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE brands (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL UNIQUE,   slug TEXT NOT NULL UNIQUE,   logo TEXT,   created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE wishlist_items (   id INTEGER PRIMARY KEY AUTOINCREMENT,   user_id TEXT NOT NULL,   product_id INTEGER NOT NULL,   created_at TEXT DEFAULT CURRENT_TIMESTAMP,   UNIQUE(user_id, product_id),   FOREIGN KEY (product_id) REFERENCES products(id) );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_cart_user_id ON cart(user_id);
CREATE INDEX idx_orders_user_id ON orders(user_id);
CREATE INDEX idx_orders_status  ON orders(status);
CREATE INDEX idx_order_items_order_id ON order_items(order_id);
CREATE UNIQUE INDEX idx_orders_stripe_session_id ON orders(stripe_session_id);
CREATE INDEX idx_email ON users(email);
CREATE INDEX idx_google_id ON users(google_id);
CREATE INDEX idx_role_status ON users(role, status);
CREATE INDEX idx_products_status ON products(status);
CREATE UNIQUE INDEX idx_users_public_id ON users(public_id);
